const UNITS: Unit[] = DATA.units;
const TOTAL_PHRASES: number = UNITS.reduce((n: number, u: Unit) => n + u.p.length, 0);
const TOTAL_LISTEN: number = UNITS.reduce((n: number, u: Unit) => n + u.li.length, 0);
const TOTAL_TURNS: number = UNITS.reduce((n: number, u: Unit) => n + u.l.filter((l: Line) => l[0] === "y").length, 0);
const UNIT_TITLE: Record<string, string> = Object.fromEntries(UNITS.map((u: Unit) => [u.id, u.t]));

function trackLine(id: string): string {
  const us = UNITS.filter((u: Unit) => u.tr === id);
  const name = DATA.tracks.find((t) => t[0] === id)?.[1] ?? id;
  return `${name}: ${us.length} units, ${us.reduce((n: number, u: Unit) => n + u.p.length, 0)} phrases`;
}

const SUMMARY: string = `${UNITS.length} units and ${TOTAL_PHRASES} phrases (${trackLine("family")}; ${trackLine("around")}), plus ${TOTAL_LISTEN} listening items and ${TOTAL_TURNS} role-play answer turns, generated from data/speak.json.`;

function say(o: Opt): string {
  const kana = o[1] ? `${o[1]} · ` : "";
  return `${o[0]}  (${kana}${o[2]}) — ${o[3]}`;
}

function phraseRows(u: Unit): TableCell[][] {
  return u.p.map((p: Phrase) => {
    const note = [p[4], p[5] ? `Grammar bite: ${p[5]}` : ""].filter((s: string) => s !== "").join(" · ");
    return [p[0], p[1] || "(same)", p[2], p[3], note];
  });
}

function listenItems(it: Listen): PropertyItem[] {
  const items: PropertyItem[] = [
    { label: "Reading", value: it[1] || "(same)" },
    { label: "Romaji", value: it[2] },
    { label: "English", value: it[3] },
    { label: "Correct meaning", value: it[4][0] },
    { label: "Distractor meanings", value: it[4].slice(1).join(" / ") },
    { label: "Reply task", value: it[5] },
    { label: "Correct reply", value: say(it[6][0]) },
    { label: "Distractor replies", value: it[6].slice(1).map((o: Opt) => say(o)).join("  |  ") },
  ];
  if (it[7]) items.push({ label: "Note", value: it[7] });
  return items;
}

function scriptRows(u: Unit): Row[] {
  const rows: Row[] = [];
  u.l.forEach((l: Line) => {
    if (l[0] === "t") {
      const bits = [l[3], l[4], l[5]].filter((s: string) => s !== "").join(" · ");
      rows.push({ lead: l[1], title: l[2], detail: l[6] ? `${bits} · Note: ${l[6]}` : bits, meta: l[7] ? "Played fast" : undefined });
    } else {
      rows.push({ lead: "You (Eliz)", title: `Your turn: ${l[1]}`, detail: l[2] || undefined });
      l[3].forEach((o: Opt, i: number) => {
        const bits = [o[1], o[2], o[3]].filter((s: string) => s !== "").join(" · ");
        rows.push({
          lead: i === 0 ? "Answer" : "Distractor",
          title: o[0],
          detail: bits,
          status: i === 0 ? { label: "Correct", tone: "success" } : { label: "Distractor", tone: "warning" },
        });
      });
    }
  });
  return rows;
}

const FLAG_LABEL: Record<Flag[0], string> = { fix: "Fix", check: "Native check", confirm: "Confirm with Shota" };

function flagRows(kind: Flag[0]): Row[] {
  return DATA.flags.filter((f: Flag) => f[0] === kind).map((f: Flag) => ({
    lead: UNIT_TITLE[f[1]] ?? f[1],
    title: f[2],
    detail: f[3],
    status: kind === "fix" ? { label: FLAG_LABEL[kind], tone: "danger" } : kind === "check" ? { label: FLAG_LABEL[kind], tone: "warning" } : { label: FLAG_LABEL[kind] },
  }));
}

function countFlags(kind: Flag[0]): number {
  return DATA.flags.filter((f: Flag) => f[0] === kind).length;
}

export default function ContentReview() {
  const [track, setTrack] = useState<string>("family");
  const [unitId, setUnitId] = useState<string>("f-meet");
  const trackUnits: Unit[] = useMemo(() => UNITS.filter((u: Unit) => u.tr === track), [track]);
  const unit: Unit = trackUnits.find((u: Unit) => u.id === unitId) ?? trackUnits[0];

  const onTrack = (v: string): void => {
    setTrack(v);
    const first = UNITS.find((u: Unit) => u.tr === v);
    if (first) setUnitId(first.id);
  };
  const onUnit = (v: string): void => setUnitId(v);

  return (
    <Page title="Eliz's Japanese lessons: content review" summary={SUMMARY} width="wide" lang="ja">
      <Section heading="Daily lesson format">
        <Text>
          Home is one big Today&apos;s lesson button, a streak, and a 28-day practice heatmap. Missing a day has no penalty — she just resumes. Each session (~10–12 min) runs: (1) Warm-up review of Leitner-due phrases (cap ~8, speak aloud), (2) 3/5/7 new phrases along an interleaved Family ↔ Getting-around curriculum, (3) a short mini conversation mixing today&apos;s new lines with earlier ones, (4) quick listen of 3–4 lines answered out loud. End screen shows streak and a peek at tomorrow. Units stay as the hidden curriculum order; Free practice opens any unit&apos;s phrases / role-play / quiz. Settings add daily new-phrase count (3/5/7). Progress stays in localStorage with a graceful migrate.
        </Text>
        <Text>
          Tone note: Eliz has already met Shota&apos;s parents. The family track is warm returning-visitor conversation (light です/ます with parents, plain form OK with siblings/peers) — not first-meeting formality. Family nickname is リズちゃん; she self-intros as リズ. Personal details confirmed with Shota (job, how they met, 2 years, younger brother, hometowns Irvine+Seoul, hobbies, travel wishes, お父さん/お母さん). No [PLACEHOLDER] tags remain in speak.json. Default daily new-phrase count is 3. A few native-tone checks are still listed below.
        </Text>
      </Section>
      <Section heading="Pick a unit">
        <Segmented<string>
          options={DATA.tracks.map((t) => ({ value: t[0], label: t[1], count: UNITS.filter((u: Unit) => u.tr === t[0]).length }))}
          value={track}
          onChange={onTrack}
        />
        <Select<string>
          label="Unit"
          options={trackUnits.map((u: Unit, i: number) => ({ value: u.id, label: `${i + 1}. ${u.t} (${u.jt})` }))}
          value={unit.id}
          onChange={onUnit}
        />
      </Section>

      <Section heading={`${unit.t} · ${unit.jt}`}>
        <Text>{unit.s}</Text>
        <Properties
          items={[
            { label: "Phrases", value: String(unit.p.length) },
            { label: "Listening items", value: String(unit.li.length) },
            { label: "Role-play", value: `${unit.rp.title} (${unit.l.filter((l: Line) => l[0] === "y").length} answer turns)` },
          ]}
        />
      </Section>

      <Section heading="Phrases" caption="Note includes the grammar bite when the card has one.">
        <Table columns={["Japanese", "Reading (kana)", "Romaji", "English", "Note"]} rows={phraseRows(unit)} />
      </Section>

      <Section heading="Listening drill" caption="She hears the line, picks its meaning, then picks a reply. The first option is the correct one.">
        {unit.li.map((it: Listen, i: number) => (
          <Section key={`${unit.id}-li-${i}`} heading={`${i + 1}. ${it[0]}`}>
            <Properties items={listenItems(it)} />
          </Section>
        ))}
      </Section>

      <Section heading={`Role-play: ${unit.rp.title}`} caption={unit.rp.setting}>
        <Rows rows={scriptRows(unit)} />
      </Section>

      <Section
        heading="Worth a check before she starts"
        caption={`${DATA.flags.length} items: ${countFlags("check")} native-speaker / resolved-detail checks, ${countFlags("confirm")} personal details still open (should be 0). All Shota placeholders cleared.`}
      >
        <Section heading="Native-speaker check">
          <Rows rows={flagRows("check")} />
        </Section>
        <Section heading="Personal details to confirm">
          <Rows rows={flagRows("confirm")} />
        </Section>
      </Section>
    </Page>
  );
}
